\begin{definition}
\label{def:8-57-extra-2}

\uses{prop:8-19}



For a diffeomorphism $F\colon M\to N$ and $X\in\mathfrak{X}(M)$, the unique
$F$-related field is the \emph{pushforward} $F_*X$, given by
\[
(F_*X)_q=dF_{F^{-1}(q)}(X_{F^{-1}(q)}). \tag{8.7}
\]
\end{definition}

